head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setDisabled]<br/>파라미터에 맞게 특정 단위의 disabled 속성값을 설정합니다.",
    "validation" : [
        "type 파라미터값이 'grid' 이면 GridView 의 disabled 속성값을 설정해야 합니다.",
        "type 파라미터값이 'row' 이면 Row 단위의 disabled 속성값을 설정하며 setRowDisabled() 메소드와 동일하게 동작해야 합니다.",
        "type 파라미터값이 'column' 이면 Column 단위의 disabled 속성값을 설정하며 setColumnDisabled() 메소드와 동일하게 동작해야 합니다.",
        "type 파라미터값이 'cell' 이면 Cell 단위의 disabled 속성값을 설정하며 setCellDisabled() 메소드와 동일하게 동작해야 합니다.",
        "rowIndex(필수) 파라미터로 type 파라미터값이 'row','cell' 일때 disabled 속성을 설정할 Row 의 인덱스를 설정할 수 있어야 합니다. (Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.)",
        "colInfo(필수) 파라미터로 type 파라미터값이 'column','cell' 일때 disabled 속성을 설정할 Column 과 Cell 의 인덱스를 설정할 수 있어야 합니다. (Column 의 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.)",
        "disabled 파라미터를 true 로 설정 시 type 파라미터값에 해당하는 단위를 비활성화(disabled) 상태로 설정해야 합니다.",
        "disabled 파라미터를 false 로 설정 시 type 파라미터값에 해당하는 단위의 비활성화(disabled) 상태를 해제해야 합니다.",
        "disabled 파라미터를 '' 로 설정 시 상위 모듈의 비활성화(disabled) 상태가 적용되어야 합니다. (type 파라미터값이 'grid' 인 경우 설정할 수 없습니다.)",
        "disabled(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="type(grid/row/column/cell) 별 setDisabled 후 getDisabled 로 결과 확인 / 우선순위 : GridView, [Row 또는 Column], Cell 순 (Cell 최우선) / Column 1 → 숨김 (숨겨진 Column 도 인덱스 포함)"', '', 'label1');

    // 조건 설정 (disabled Cell 을 배경색으로 구분: disabled=회색, readonly=연노랑)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 두번째 컬럼 숨김 (숨겨진 Column 도 인덱스에 포함됨을 검증)
    target1.setColumnVisible(1, false);
}



scwin.btn_setDisabled_onclick = function () {
    let type = par_type.getValue();
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = Number(par_colInfo.getText());
    let disabledText = par_disabled.getValue();

    // disabled 파라미터 값 결정 (true / false / '' / 생략)
    if (disabledText === 'omit') {
        // 파라미터 생략 → 기본값 false
        if (type === 'grid') {
            target1.setDisabled(type);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('grid')");
        } else if (type === 'row') {
            target1.setDisabled(type, rowIndex);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('row', " + rowIndex + ")");
        } else if (type === 'column') {
            target1.setDisabled(type, colInfo);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('column', " + colInfo + ")");
        } else {
            target1.setDisabled(type, rowIndex, colInfo);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('cell', " + rowIndex + ", " + colInfo + ")");
        }
    } else {
        // true / false / '' (빈 문자열) 설정
        let disabled = (disabledText === 'true') ? true : (disabledText === 'false') ? false : "";

        if (type === 'grid') {
            // grid 는 '' 설정 불가 → 가이드 명시
            if (disabled === "") {
                wf_body_bottom.getObj("scwin").setReturnValue("type 'grid' 인 경우 disabled '' 설정 불가");
                return;
            }
            target1.setDisabled(type, disabled);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('grid', " + disabled + ")");
        } else if (type === 'row') {
            target1.setDisabled(type, rowIndex, disabled);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('row', " + rowIndex + ", " + JSON.stringify(disabled) + ")");
        } else if (type === 'column') {
            target1.setDisabled(type, colInfo, disabled);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('column', " + colInfo + ", " + JSON.stringify(disabled) + ")");
        } else {
            target1.setDisabled(type, rowIndex, colInfo, disabled);
            wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('cell', " + rowIndex + ", " + colInfo + ", " + JSON.stringify(disabled) + ")");
        }
    }

    scwin.btn_getDisabled_onclick();
}



scwin.btn_getDisabled_onclick = function () {
    let type = par_type.getValue();
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = Number(par_colInfo.getText());

    // 설정한 단위(type) 의 disabled 상태 조회
    if (type === 'grid') {
        wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('grid') : " + target1.getDisabled("grid"));
    } else if (type === 'row') {
        wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('row', " + rowIndex + ") : " + target1.getDisabled("row", rowIndex));
    } else if (type === 'column') {
        wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('column', " + colInfo + ") : " + target1.getDisabled("column", colInfo));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('cell', " + rowIndex + ", " + colInfo + ") : " + target1.getDisabled("cell", rowIndex, colInfo));
    }

    // 전체 셀의 실제 적용 disabled 상태 격자 출력 (getDisabled('all', r, c))
    let rowCount = dlt_bind.getRowCount();
    let colCount = target1.getColumnCount();
    for (let r = 0; r < rowCount; r++) {
        let states = [];
        for (let c = 0; c < colCount; c++) {
            states.push("c" + c + "=" + target1.getDisabled("all", r, c));
        }
        wf_body_bottom.getObj("scwin").setReturnValue("Row" + r + " : " + states.join(", "));
    }
}
